local a=peripheral.find("inventory")if not peripheral.hasType(a,"inventory")then return end;local b=a;b.itemTypes={}b.freeSpace=0;print("[storage] indexing ...")local c=b.list()for d=1,#c do local e=b.getItemDetail(d)if e==nil then print("empty")b.freeSpace=b.freeSpace+64 elseif not b.itemTypes[e.name]then table.insert(b.itemTypes,{e.name,e.displayName,e.maxCount})end;if d%10==1 then print("[storage] indexing: "..d/#c*100 .."%")end end;b.freeSpace=b.freeSpace+(b.size()-#c)*64;print("[storage] indexing complete.")print("[storage] free space: "..b.freeSpace)function b.count()local f=0;for d,g in pairs(b.list())do if g~=nil and g.count~=nil then f=f+g.count end end;return f end;function b.maxCount()local f=(b.size()-#b.list())*64;for d,g in pairs(b.list())do if g~=nil then maxToAdd=64;if b.itemTypes[g.name]then maxToAdd=b.itemTypes[g.name]end;f=f+maxToAdd end end;return f end;function b.percentage()return math.floor(b.count()/b.maxCount()*100)end;return b
